      objective: "test",
      verificationCommand: "node -e \"process.exit(0)\"",
      minVerifiedCandidates: 1,
      maxRounds: 2,
    };
    let callCount = 0;
    const dispatch = async () => {
      callCount++;
      return { actions: [] };
    };
    await runMission(mission, dispatch);
    assert.equal(callCount, 2);
  });

  it("stops contracting inference waves as soon as minVerifiedCandidates is satisfied", async () => {
    const mission = {
      objective: "fix calc",
      verificationCommand: `node -e "const c=require('fs').readFileSync('calc.mjs','utf8');process.exit(c.includes('a + b')?0:1)"`,
      minVerifiedCandidates: 1,
      maxRounds: 10,
    };

    let dispatchCount = 0;
    const dispatch = async () => {
      dispatchCount++;
      return {
        actions: [
          {
            action: "edit",
            path: "calc.mjs",
            content: "export function calc(a, b) { return a + b; }\n",
          },
        ],
      };
    };

    const result = await runMission(mission, dispatch);

    assert.equal(dispatchCount, 1, "dispatch must not be called again after minVerifiedCandidates is satisfied");
    assert.equal(result.verifiedCandidates.length, 1);
    assert.ok(result.candidates[0].verified);
  });
});"}]}}
